import { yearsBetween, humanEquivalent, calendarAge, lifeStage } from "./calculator.mjs";
const form=document.querySelector("#pet-form"),birthInput=document.querySelector("#birth-date"),nameInput=document.querySelector("#pet-name"),sizeField=document.querySelector("#dog-size-field"),sizeSelect=document.querySelector("#dog-size"),error=document.querySelector("#birth-error"),emptyResult=document.querySelector("#empty-result"),resultContent=document.querySelector("#result-content"),resultCard=document.querySelector("#result-card"),storageKey="petAgeProfileV1";
birthInput.max=localISODate(new Date());restore();update();
form.addEventListener("input",update);form.addEventListener("change",update);document.querySelector("#reset-button").addEventListener("click",()=>{form.reset();localStorage.removeItem(storageKey);error.textContent="";birthInput.classList.remove("invalid");update();form.querySelector('input[name="species"]').focus()});document.addEventListener("visibilitychange",()=>{if(!document.hidden)update()});setInterval(update,60_000);
function update(){const data=new FormData(form),species=data.get("species"),birthDate=data.get("birthDate"),dogSize=data.get("dogSize")||"medium",petName=String(data.get("petName")||"").trim();sizeField.hidden=species!=="dog";if(birthDate&&yearsBetween(birthDate)===null){error.textContent="วันเกิดต้องไม่เกินวันนี้ กรุณาตรวจสอบวันที่อีกครั้ง";birthInput.classList.add("invalid");showEmpty();return}error.textContent="";birthInput.classList.remove("invalid");if(!species||!birthDate){showEmpty();persist({species,birthDate,dogSize,petName});return}const years=yearsBetween(birthDate),humanYears=Math.round(humanEquivalent(species,years,dogSize)),actual=calendarAge(birthDate),stage=lifeStage(species,years,dogSize),ageText=formatAge(actual);emptyResult.hidden=true;resultContent.hidden=false;resultCard.classList.remove("is-empty");document.querySelector("#result-kicker").textContent=petName?`วันนี้${petName}อายุเทียบเท่าคนประมาณ`:"วันนี้น้องอายุเทียบเท่าคนประมาณ";document.querySelector("#human-years").textContent=humanYears.toLocaleString("th-TH");document.querySelector("#actual-age").textContent=ageText;document.querySelector("#stage-badge").textContent=stage.label;document.querySelector("#timeline-progress").style.width=`${[12,38,67,100][stage.index]}%`;const now=new Date(),time=document.querySelector("#updated-at");time.dateTime=now.toISOString();time.textContent=new Intl.DateTimeFormat("th-TH",{dateStyle:"medium",timeStyle:"short"}).format(now);resultCard.setAttribute("aria-label",`ผลการคำนวณ: ${petName||"สัตว์เลี้ยง"}อายุจริง ${ageText} เทียบเท่าอายุคนประมาณ ${humanYears} ปี อยู่ในช่วง${stage.label}`);resultCard.classList.remove("is-updating");requestAnimationFrame(()=>resultCard.classList.add("is-updating"));persist({species,birthDate,dogSize,petName})}
function showEmpty(){emptyResult.hidden=false;resultContent.hidden=true;resultCard.classList.add("is-empty");resultCard.removeAttribute("aria-label")}
function formatAge(age){if(!age||(age.years===0&&age.months===0&&age.days===0))return"น้อยกว่า 1 วัน";return[[age.years,"ปี"],[age.months,"เดือน"],[age.days,"วัน"]].filter(([value])=>value>0).map(([value,unit])=>`${value.toLocaleString("th-TH")} ${unit}`).join(" ")}
function persist(profile){localStorage.setItem(storageKey,JSON.stringify(profile))}
function restore(){try{const saved=JSON.parse(localStorage.getItem(storageKey));if(!saved)return;if(saved.species)form.elements.species.value=saved.species;nameInput.value=saved.petName||"";birthInput.value=saved.birthDate||"";sizeSelect.value=saved.dogSize||"medium"}catch{localStorage.removeItem(storageKey)}}
function localISODate(date){const offset=date.getTimezoneOffset()*60_000;return new Date(date.getTime()-offset).toISOString().slice(0,10)}
